def tryfit(f,p0s):
    best=None
    for p0 in p0s:
        try:
            def res(p):
                A=np.column_stack([np.ones_like(ts)]+list(f(ts,p)));c=np.linalg.lstsq(A,ys,rcond=None)[0];return A@c-ys
            r=least_squares(res,p0,x_scale='jac',max_nfev=150)
            if best is None or r.cost<best.cost:best=r
        except Exception as e: pass
    p=best.x;A=np.column_stack([np.ones_like(ts)]+list(f(ts,p)));c=np.linalg.lstsq(A,ys,rcond=None)[0]
    return ('%.2e'%(2*best.cost/len(ts)/np.var(dP_dt)),p.round(4),c.round(4))
